package com.flowdesk.ticket;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.data.domain.Page; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1") public class TicketController {
 private final TicketService service;private final Clock clock;public TicketController(TicketService s,Clock c){service=s;clock=c;}
 @GetMapping("/tickets") public Page<TicketView> list(Authentication a,@RequestParam(required=false)String status,@RequestParam(required=false)String priority,@RequestParam(required=false)String category,@RequestParam(required=false)String assignee,@RequestParam(required=false)String q,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant from,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE_TIME)Instant to,@RequestParam(required=false)Boolean breached,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){boolean all=has(a,"ADMIN")||has(a,"MANAGER")||has(a,"AUDITOR");return service.list(a.getName(),all,status,priority,category,assignee,q,from,to,breached,page,size).map(t->TicketView.from(t,clock.instant()));}
 @PostMapping("/tickets") @PreAuthorize("hasAnyRole('EMPLOYEE','ADMIN','MANAGER')") public TicketView create(@Valid @RequestBody CreateBody r,Authentication a){var x=service.create(new TicketService.CreateTicket(r.title(),r.description(),r.category(),r.priority()),a.getName());return TicketView.from(x,clock.instant());}
 @GetMapping("/tickets/{id}") public TicketView get(@PathVariable long id,Authentication a){boolean all=has(a,"ADMIN")||has(a,"MANAGER")||has(a,"AUDITOR");return TicketView.from(service.get(id,a.getName(),all),clock.instant());}
 @PostMapping("/tickets/{id}/assign") @PreAuthorize("hasAnyRole('ADMIN','MANAGER')") public TicketView assign(@PathVariable long id,@Valid @RequestBody AssignBody r,Authentication a){return TicketView.from(service.assign(id,r.username(),a.getName()),clock.instant());}
 @PatchMapping("/tickets/{id}/priority") @PreAuthorize("hasAnyRole('ADMIN','MANAGER')") public TicketView priority(@PathVariable long id,@Valid @RequestBody PriorityBody r,Authentication a){return TicketView.from(service.setPriority(id,r.priority(),r.reason(),a.getName()),clock.instant());}
 @PostMapping("/tickets/{id}/actions/{action}") @PreAuthorize("hasAnyRole('ADMIN','MANAGER','EMPLOYEE')") public TicketView action(@PathVariable long id,@PathVariable String action,@RequestBody(required=false)ActionBody r,Authentication a){Set<String> roles=new HashSet<>();for(var x:a.getAuthorities())if(x.getAuthority().startsWith("ROLE_"))roles.add(x.getAuthority().substring(5));return TicketView.from(service.transition(id,action.toUpperCase(),r==null?null:r.reason(),a.getName(),roles),clock.instant());}
 @GetMapping("/tickets/{id}/audit") @PreAuthorize("hasAnyRole('ADMIN','MANAGER','AUDITOR')") public List<TicketAudit> audit(@PathVariable long id){return service.history(service.get(id,"",true).getTicketNumber());}
 @GetMapping("/audit") @PreAuthorize("hasAnyRole('ADMIN','MANAGER','AUDITOR')") public List<TicketAudit> allAudit(){return service.allAudit();}
 @GetMapping("/notifications") public List<Notification> notifications(Authentication a){return service.myNotifications(a.getName());}
 @PostMapping("/notifications/{id}/read") public Notification read(@PathVariable long id,Authentication a){return service.markRead(id,a.getName());}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(Authentication a){boolean all=has(a,"ADMIN")||has(a,"MANAGER")||has(a,"AUDITOR");var page=service.list(a.getName(),all,null,null,null,null,null,null,null,null,0,100);var tickets=page.getContent();long completed=tickets.stream().filter(t->t.getStatus().equals("COMPLETED")).count();long active=tickets.stream().filter(t->!List.of("COMPLETED","CANCELLED").contains(t.getStatus())).count();long dueSoon=tickets.stream().filter(t->!List.of("COMPLETED","CANCELLED").contains(t.getStatus())&&t.getSlaDueAt().isBefore(clock.instant().plusSeconds(4*3600L))).count();double completionRate=tickets.isEmpty()?0.0:(completed*100.0/tickets.size());return Map.of("total",page.getTotalElements(),"slaBreaches",tickets.stream().filter(t->t.isSlaBreached(clock.instant())).count(),"dueSoon",dueSoon,"completionRate",completionRate,"pendingApproval",tickets.stream().filter(t->t.getStatus().equals("PENDING_APPROVAL")).count(),"open",active);}
 private boolean has(Authentication a,String role){return a.getAuthorities().contains(new SimpleGrantedAuthority("ROLE_"+role));}
 public record CreateBody(@NotBlank @Size(max=180)String title,@NotBlank @Size(max=10000)String description,@NotBlank String category,@Pattern(regexp="P1|P2|P3")String priority){} public record AssignBody(@NotBlank String username){} public record PriorityBody(@Pattern(regexp="P1|P2|P3")String priority,@NotBlank String reason){} public record ActionBody(String reason){}
}
